// Test compiler: freezes a successful exploration trace into a standalone,
// deterministic test script. The generated file imports only the driver
// layer — no planner, no provider, no LLM. Every step replays the exact
// locator spec the explorer recorded (testId + role + name + text + CSS
// path, tried in that order by the shared grounding helper), with explicit
// quiescence waits after each action and polling assertion waits at the
// end. On failure it prints a QA_RESULT JSON line carrying the failure
// phase plus grounding diagnostics for the failure classifier.

const RUNTIME = `
function matchDescriptor(elements, spec) {
  if (!spec) return [];
  if (spec.testId) {
    const m = elements.filter((e) => e.testId === spec.testId);
    if (m.length) return m;
  }
  if (spec.role && spec.name) {
    const target = String(spec.name).toLowerCase();
    const m = elements.filter((e) => e.role === spec.role && (e.name || "").toLowerCase() === target);
    if (m.length) return m;
  }
  if (spec.text) {
    const m = elements.filter((e) => e.text === spec.text);
    if (m.length) return m;
  }
  if (spec.css && spec.id) return elements.filter((e) => e.id === spec.id);
  return [];
}

function evaluateAssertion(a, snapshot) {
  switch (a.kind) {
    case "element": {
      const m = matchDescriptor(snapshot.elements, a.find).filter((e) => e.visible);
      if (!m.length) return { pass: false, matchedAny: false, detail: "element not found/visible: " + JSON.stringify(a.find) };
      if (a.textContains && !m[0].text.includes(a.textContains))
        return { pass: false, matchedAny: true, detail: "element text \\"" + m[0].text + "\\" does not contain \\"" + a.textContains + "\\"" };
      return { pass: true, matchedAny: true, detail: "element present" };
    }
    case "elementAbsent": {
      const m = matchDescriptor(snapshot.elements, a.find).filter((e) => e.visible);
      return m.length
        ? { pass: false, matchedAny: true, detail: "element unexpectedly present: " + JSON.stringify(a.find) }
        : { pass: true, matchedAny: false, detail: "element absent as expected" };
    }
    case "elementText": {
      const m = matchDescriptor(snapshot.elements, a.find);
      if (!m.length) return { pass: false, matchedAny: false, detail: "element not found: " + JSON.stringify(a.find) };
      const ok = a.equals !== undefined ? m[0].text === a.equals : m[0].text.includes(a.contains || "");
      return { pass: ok, matchedAny: true, detail: "element text \\"" + m[0].text + "\\"" };
    }
    case "text": {
      const ok = snapshot.pageText.includes(a.text);
      return { pass: ok, matchedAny: true, detail: ok ? "page contains text" : "page missing text \\"" + a.text + "\\"" };
    }
    case "view": {
      const ok = snapshot.hash === a.hash;
      return { pass: ok, matchedAny: true, detail: "hash " + snapshot.hash + " vs expected " + a.hash };
    }
    default:
      return { pass: false, matchedAny: true, detail: "unknown assertion kind " + a.kind };
  }
}

async function waitForAssertion(driver, assertion, timeoutMs) {
  const start = Date.now();
  let last = { pass: false, matchedAny: false, detail: "no snapshot taken" };
  while (Date.now() - start < (timeoutMs || 6000)) {
    const snap = await driver.snapshot();
    last = evaluateAssertion(assertion, snap);
    if (last.pass) return last;
    await new Promise((r) => setTimeout(r, 100));
  }
  return last;
}

// Diagnostics about how this run's own actions grounded. An act "drifted"
// when its recorded spec carried a testId but a fallback strategy had to be
// used instead — evidence the page surface has shifted under the test. The
// failure classifier uses this to tell a missing behavior on an intact page
// (product bug) from a generally drifted page (test rot).
const ACT_LOG = [];
function actDiagnostics() {
  const drifted = ACT_LOG.filter((a) => a.hadTestId && a.strategy !== "testid").length;
  return { total: ACT_LOG.length, drifted: drifted };
}

function fail(phase, detail, extra) {
  console.log("QA_RESULT " + JSON.stringify(Object.assign({ status: "fail", phase: phase, detail: detail }, extra || {})));
  process.exit(1);
}
`;

export function compileTrace(trace) {
  const lines = [];
  lines.push(`// COMPILED REGRESSION TEST — generated by the test compiler from a`);
  lines.push(`// successful exploration trace. Deterministic: no agent, no planner,`);
  lines.push(`// no LLM at replay time. Do not edit by hand; recompile instead.`);
  lines.push(`// Flow: ${trace.flowId} — ${trace.task}`);
  lines.push(`// Explored with driver=${trace.driver}, provider=${trace.provider}, at ${trace.startedAt}.`);
  lines.push(`import { createDriver } from "../src/driver/driver.mjs";`);
  lines.push(``);
  lines.push(`const APP_URL = process.env.QA_APP_URL;`);
  lines.push(`if (!APP_URL) fail("environment", "QA_APP_URL env var not set");`);
  lines.push(RUNTIME);

  lines.push(``);
  lines.push(`async function main() {`);
  lines.push(`  let driver;`);
  lines.push(`  try {`);
  lines.push(`    driver = await createDriver({ origin: new URL(APP_URL).origin });`);
  lines.push(`  } catch (e) { fail("environment", "driver start failed: " + String(e && e.message || e)); }`);
  lines.push(`  try {`);
  lines.push(`    await driver.goto(APP_URL);`);

  for (const step of trace.steps) {
    if (step.skipped) {
      lines.push(`    // step ${step.n} skipped during exploration: ${step.skipped}`);
      continue;
    }
    if (step.assertion) {
      lines.push(`    // step ${step.n} (assertion): ${step.intent}`);
      lines.push(`    {`);
      lines.push(`      const r = await waitForAssertion(driver, ${JSON.stringify(step.assertion)});`);
      lines.push(`      if (!r.pass) {`);
      lines.push(`        fail("assertion", "step ${step.n}: " + r.detail, { assertion: ${JSON.stringify(step.assertion)}, matchedAny: r.matchedAny, acts: actDiagnostics() });`);
      lines.push(`      }`);
      lines.push(`    }`);
      continue;
    }
    if (step.action) {
      const spec = step.recordedSpec || step.target;
      lines.push(`    // step ${step.n}: ${step.intent} (exploration grounded via "${step.strategyUsed}")`);
      lines.push(`    {`);
      lines.push(`      const res = await driver.act(${JSON.stringify(spec)}, ${JSON.stringify(step.action)});`);
      lines.push(`      if (!res.ok) fail(res.phase || "grounding", "step ${step.n} action failed", { grounding: res.strategies || [] });`);
      lines.push(`      ACT_LOG.push({ hadTestId: ${JSON.stringify(!!(spec.testId))}, strategy: res.strategy });`);
      lines.push(`      await driver.waitForQuiescence();`);
      lines.push(`    }`);
    }
  }

  lines.push(`    // final assertions (from exploration verdict)`);
  for (const { assertion } of trace.assertions) {
    if (assertion.kind === "injectionFlagged") {
      lines.push(`    // (exploration-only assertion skipped at replay: ${assertion.kind})`);
      continue;
    }
    lines.push(`    {`);
    lines.push(`      const r = await waitForAssertion(driver, ${JSON.stringify(assertion)});`);
    lines.push(`      if (!r.pass) {`);
    lines.push(`        fail("assertion", r.detail, { assertion: ${JSON.stringify(assertion)}, matchedAny: r.matchedAny, acts: actDiagnostics() });`);
    lines.push(`      }`);
    lines.push(`    }`);
  }

  lines.push(`    console.log('QA_RESULT {"status":"pass"}');`);
  lines.push(`    await driver.close();`);
  lines.push(`  } catch (e) {`);
  lines.push(`    if (e && (e.code === "ENVIRONMENT" || e.code === "ORIGIN_BLOCKED")) fail("environment", String(e.message || e));`);
  lines.push(`    fail("environment", "unexpected error: " + String(e && e.message || e));`);
  lines.push(`  }`);
  lines.push(`}`);
  lines.push(`main();`);
  lines.push(``);
  return lines.join("\n");
}
